#include <cuda_runtime.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>

struct Tally { float sum; float sq; unsigned int count; };

__device__ inline unsigned int lcg(unsigned int& s) {
    s = s * 1664525u + 1013904223u;
    return s;
}
__device__ inline float gauss(unsigned int& s) {
    float u1 = lcg(s) * 2.3283064e-10f;
    float u2 = lcg(s) * 2.3283064e-10f;
    return sqrtf(-2.0f * logf(u1)) * cosf(6.2831855f * u2);
}

__global__ void asian_kernel(float S, float K, float drift, float vol, int n, 
                             unsigned long long nPaths, unsigned int seed, Tally* tally) {
    unsigned int tid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned int total_threads = gridDim.x * blockDim.x;

    // Each thread processes multiple paths if needed
    unsigned long long paths_per_thread = (nPaths + total_threads - 1) / total_threads;
    unsigned long long start_path = tid * paths_per_thread;
    unsigned long long end_path = min(start_path + paths_per_thread, nPaths);

    // Initialize local tally for this thread
    Tally local_tally = {0.0f, 0.0f, 0};

    for (unsigned long long p = start_path; p < end_path; p++) {
        // Initialize random state for this path
        unsigned int state = seed * 2654435761u + p;
        for (int i = 0; i < 16; i++) lcg(state);

        float x = 0, sum = 0;
        for (int k = 0; k < n; k++) {
            x += drift + vol * gauss(state);
            sum += S * expf(x);
        }
        float pay = sum / n - K;
        if (pay < 0) pay = 0;

        local_tally.sum += pay;
        local_tally.sq += pay * pay;
        local_tally.count++;
    }

    // Atomic addition to global tally
    atomicAdd(&tally[0].sum, local_tally.sum);
    atomicAdd(&tally[0].sq, local_tally.sq);
    atomicAdd(&tally[0].count, local_tally.count);
}

McResult gpu_asian_call(double S, double K, double r, double sigma, double T, int n,
                        unsigned long long nPaths, unsigned int seed, int device) {
    cudaSetDevice(device);

    // Use reasonable grid size to avoid memory issues
    const int threads = 256;
    const int max_blocks = 1024;  // Limit to avoid memory issues
    int blocks = (int)((nPaths + threads - 1) / threads);
    if (blocks > max_blocks) blocks = max_blocks;

    // Allocate memory for tally
    Tally* d;
    cudaMalloc(&d, sizeof(Tally));
    Tally zero = {0, 0, 0};
    cudaMemcpy(d, &zero, sizeof(Tally), cudaMemcpyHostToDevice);

    float dt = T / n;  // Correct time step
    float drift = (r - 0.5 * sigma * sigma) * dt, vol = sigma * sqrt(dt);

    // Launch kernel
    asian_kernel<<<blocks, threads>>>(S, K, drift, vol, n, nPaths, seed, d);

    // Check for kernel launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\n", cudaGetErrorString(err));
    }

    // Wait for kernel completion
    cudaDeviceSynchronize();

    // Copy result back
    Tally h;
    cudaMemcpy(&h, d, sizeof(Tally), cudaMemcpyDeviceToHost);

    // Clean up
    cudaFree(d);

    // Calculate final results
    double m = double(h.sum) / h.count;
    double v = double(h.sq) / h.count - m * m;
    double df = exp(-r * T);

    // Standard error calculation: sqrt(variance / nPaths)
    double std_error = df * sqrt(v / h.count);

    return {df * m, std_error, h.count};
}

